import SwiftUI

/// Choose the Home Screen icon: the original flat one, or one of the Liquid Glass alternates (Icon Composer
/// documents in `Resources/AppIcons`, generated by `icons/build_icons.py` and listed in
/// `ASSETCATALOG_COMPILER_ALTERNATE_APPICON_NAMES` in project.yml). The thumbnails are renders of those icons
/// (`IconPreview*` in the asset catalog), because an app can't load its own icons by name.
struct AppIconPicker: View {
    @Environment(\.dismiss) private var dismiss
    @State private var current = UIApplication.shared.alternateIconName
    @State private var failure: String?

    private struct Option: Identifiable {
        let name: String?   // nil is the primary (original) icon
        let title: String
        let preview: String
        var id: String { name ?? "AppIcon" }
    }

    private let options = [
        Option(name: nil, title: "Original", preview: "IconPreviewOriginal"),
        Option(name: "AppIconGold", title: "Gold", preview: "IconPreviewGold"),
        Option(name: "AppIconGoldWhite", title: "Gold & White", preview: "IconPreviewGoldWhite"),
        Option(name: "AppIconBlue", title: "Blue", preview: "IconPreviewBlue"),
        Option(name: "AppIconBlueGold", title: "Blue & Gold", preview: "IconPreviewBlueGold"),
    ]

    var body: some View {
        NavigationStack {
            ScrollView {
                LazyVGrid(columns: [GridItem(.adaptive(minimum: 120), spacing: 20)], spacing: 24) {
                    ForEach(options) { option in
                        Button { choose(option) } label: {
                            VStack(spacing: 8) {
                                Image(option.preview)
                                    .resizable().scaledToFit()
                                    .frame(maxWidth: 120)
                                    .overlay(alignment: .bottomTrailing) {
                                        if current == option.name {
                                            Image(systemName: "checkmark.circle.fill")
                                                .font(.title2)
                                                .symbolRenderingMode(.palette)
                                                .foregroundStyle(.white, Color.aioBlue)
                                                .offset(x: 6, y: 6)
                                        }
                                    }
                                Text(option.title).font(.univers(14, relativeTo: .subheadline))
                            }
                        }
                        .buttonStyle(.plain)
                        .accessibilityLabel(option.title)
                        .accessibilityAddTraits(current == option.name ? .isSelected : [])
                    }
                }
                .padding(24)
            }
            .aioBackground("bg_celebration.jpg")
            .navigationTitle("App Icon")
            .navigationBarTitleDisplayMode(.inline)
            .toolbar { ToolbarItem(placement: .confirmationAction) { Button("Done") { dismiss() } } }
            .alert("Couldn't change the icon", isPresented: Binding(get: { failure != nil }, set: { if !$0 { failure = nil } })) {
                Button("OK", role: .cancel) {}
            } message: { Text(failure ?? "") }
        }
    }

    private func choose(_ option: Option) {
        guard option.name != current, UIApplication.shared.supportsAlternateIcons else { return }
        Task {
            do {
                try await UIApplication.shared.setAlternateIconName(option.name)
                current = option.name
            } catch {
                failure = error.localizedDescription
            }
        }
    }
}
